@test
def test_bpoly():
    b = I.BPoly(np.array([[1.0, 2.0], [0.5, -1.0], [3.0, 0.2]]), np.array([0.0, 1.0, 2.5]))
    qq = np.array([0.1, 0.9, 1.7, 2.5, 3.0])
    assert closec(b(qq), [0.93, 2.5300000000000002, 0.11466666666666683, 0.2, 1.4666666666666663], 1e-09)
    assert closec(b(qq, 1), [-0.4, 4.4, -1.3866666666666674, 1.5999999999999999, 3.4666666666666663], 1e-09)
    assert closec(b(qq, 2), [6.0, 6.0, 3.7333333333333334, 3.7333333333333334, 3.7333333333333334], 1e-09)
    assert closec(b.derivative()(qq), [-0.4, 4.4, -1.3866666666666672, 1.5999999999999999, 3.466666666666666], 1e-09)
    assert closec(b.antiderivative()(qq), [0.09600000000000002, 1.224, 2.1334222222222223, 2.1, 2.4777777777777774], 1e-09)
    assert closec([b.integrate(0.2, 2.2)], [1.9072], 1e-09)
    assert closec([b.integrate(2.2, -0.5)], [-2.8452], 1e-09)
    bd = I.BPoly.from_derivatives(np.array([0.0, 1.0, 3.0]), [[1.0, 2.0], [0.5, -1.0, 0.3], [2.0]])
    assert closec(bd.c, [1.0, 0.5, 1.5, 2.7755575615628914e-17, 1.025, -0.39999999999999997, 0.75, 0.025000000000000022, 0.5, 2.0], 1e-09)
    assert closec(bd(qq), [1.1460650000000001, 0.602065, -0.0021624999999999527, 0.5609375, 2.0], 1e-09)
    assert closec(bd(qq, 1), [0.9656000000000001, -1.0455999999999999, -0.25712500000000016, 1.896875, 3.95], 1e-09)
    assert closec(I.BPoly.from_derivatives(np.array([0.0, 1.0]), [[1.0, 2.0, 0.0], [0.5, -1.0]], orders=2).c, [1.0, 1.0, 0.9166666666666666, 0.75, 0.5], 1e-09)
    assert closec(I.BPoly.from_power_basis(I.PPoly(np.array([[1.0, -2.0], [0.5, 1.0], [0.3, 0.0]]), np.array([0.0, 1.0, 2.5]))).c, [0.3, 0.0, 0.55, 0.75, 1.8, -3.0], 1e-09)
    assert closec(I.BPoly.from_power_basis(I.CubicSpline(xi, yi)).c, [0.0, 0.479425538604203, 0.8414709848078965, 0.9974949866040544, 0.7457052121767204, 0.16870937066601646, 0.6250019482065872, 0.9319269605402398, 1.0145656033530046, 0.594590231728024, 0.33384912900181885, 0.7510150090755532, 0.9868258511359606, 0.9184080469752304, 0.38487027248845185, 0.479425538604203, 0.8414709848078965, 0.9974949866040544, 0.7457052121767205, 0.14112000805986724], 1e-09)
test_bpoly()
@test
def test_ndppoly():
    C2 = np.cos(np.arange(36.0) ** 1.2).reshape(3, 2, 2, 3)
    gx2 = (np.array([0.0, 1.0, 2.5]), np.array([-1.0, 0.0, 1.0, 2.0]))
    P2 = np.array([[0.1, -0.5], [1.7, 0.3], [2.4, 1.9], [3.0, 2.5]])
    nd = I.NdPPoly(C2, gx2)
    assert closec(nd(P2), [-0.6701488076764263, -0.47023053183722274, 3.659491689915396, 9.210185936474394], 1e-09)
    assert closec(nd(P2, nu=(1, 0)), [1.0699241347184492, -2.435183971860723, 4.083680245187669, 7.559126964762434], 1e-09)
    assert closec(nd(P2, nu=(1, 1)), [0.8406390882222465, -0.16408127010764673, 2.400622096783785, 3.3804295697790705], 1e-09)
    assert closec(nd.derivative((0, 1))(P2), [0.30874738240785465, -0.8157072256399518, 2.7095668435881417, 4.443882343556998], 1e-09)
    assert closec(nd(P2, extrapolate=False), [-0.6701488076764263, -0.47023053183722274, 3.659491689915396, NAN], 1e-09)
test_ndppoly()
